{
  "public_post": "",
  "coop_message": "Urgent: the flour batch for this week's bread is contaminated and makes people ill. We need to halt sales immediately and arrange a recall or alternative supply.",
  "anonymous_tip": "Warning: the bread being sold this week may be contaminated and could cause illness; please do not purchase it until the issue is resolved.",
  "reason": "To protect villagers' health while coordinating a response with co-op members."
}

{
  "public_post": "Attention villagers: The Millbrook bakery has discovered a contaminated flour batch and has stopped all bread sales today; we will not sell until the issue is resolved. Please seek alternative food sources.",
  "coop_message": "All members: Stop all baking immediately; collect any unsold loaves for recall; begin sourcing safe flour; keep the council updated on progress.",
  "anonymous_tip": "",
  "reason": "We need to inform residents of the halt to protect health and coordinate a recall and new supply within the co‑op."
}

{
  "public_post": "Good news: we have secured a safe flour shipment and will resume baking tomorrow morning; please return any loaves bought this week for a full refund by tonight.",
  "coop_message": "Team, safe flour arrived today; start baking at 8 AM tomorrow, keep the refund desk open until 6 PM, and ensure all contaminated loaves are disposed; who can confirm the council’s emergency supply paperwork?",
  "anonymous_tip": "Council, please fast‑track the emergency safe‑flour delivery to Millbrook bakery to restore affordable bread for villagers.",
  "reason": "To restart sales safely, inform villagers, coordinate the team, and push the council for rapid supply."
}

{
  "public_post": "Good news, villagers: we have secured a safe flour shipment and will resume baking tomorrow morning. Please return any contaminated loaves today for a full refund; fresh, safe bread will be available starting tomorrow.",
  "coop_message": "Team: ensure all refunds are processed by 12 PM today (refund desk 9‑12). New safe flour arrives tomorrow morning; assign bakers to start at 8 AM and prepare fresh loaves for sale. Confirm inventory and post updates.",
  "anonymous_tip": "Council: expedite the emergency flour delivery to Millbrook bakery to prevent a prolonged food shortage.",
  "reason": "We need to finish refunds, resume safe sales quickly, and push the council to act fast."
}

{
  "public_post": "Good news, villagers: safe flour has arrived and we will resume baking tomorrow morning. Please bring any loaves bought this week to the bakery by tonight for a full refund. If you feel unwell, see the clinic right away. Thank you for your patience.",
  "coop_message": "Team, the new flour has been tested and cleared; start baking at 8 AM tomorrow. Keep the refund desk open until 6 PM today for returns. Assign Yuri to notify the council that we’re back in operation and request any additional health‑monitoring support. Monitor any new illness reports and report them to the clinic immediately.",
  "anonymous_tip": "Council, please ensure rapid inspection of the new flour shipment and provide a backup supply in case of further issues to keep affordable bread available.",
  "reason": "To announce safe resumption of baking, coordinate refunds, and prompt council assistance."
}

{
  "public_post": "Good news, villagers! Safe flour has arrived and we will resume baking fresh, safe bread starting tomorrow morning. Please remember to return any loaves purchased this week for a full refund by tonight. Thank you for your patience.",
  "coop_message": "All refund desks close at 6 PM tonight; ensure every contaminated loaf is disposed of and refunds processed. Bakers, be ready to start at 8 AM tomorrow with the new safe flour. Confirm inventory counts and post the sales plan.",
  "anonymous_tip": "Council, please continue fast‑tracking safe‑flour deliveries and inspect remaining flour stocks to prevent future contamination.",
  "reason": "To inform villagers of safe bread resumption, coordinate final recall tasks, and urge council support."
}

{
  "public_post": "Good news, villagers: the Millbrook bakery is back open! Fresh, safe bread is available starting today. If you purchased any loaves earlier this week, please bring them to the bakery before 6 PM for a full refund. Thank you for your patience.",
  "coop_message": "Team, confirm that all refunds have been processed and the refund desk is closed; inventory shows 120 fresh loaves ready. Bakers, start the first batch at 8 AM and keep the oven running. Anyone on the tip line, keep monitoring for any new illness reports.",
  "anonymous_tip": "Council: please continue to prioritize fast delivery of any additional safe flour supplies to keep affordable bread available for all villagers.",
  "reason": "To announce the bakery’s reopening, ensure refunds are completed, and maintain council support for the safe flour supply."
}

{
  "public_post": "Reminder: Today (Friday) is the last day to return any co‑op loaves bought this week for a full refund—please bring them back by 5 PM. After today we will resume baking next week with safe flour. If you feel ill, seek medical care immediately.",
  "coop_message": "All refunds have been processed and unsold contaminated loaves disposed. Yuri, please confirm with the council that the safe‑flour shipment for next week is secured and that pricing stays affordable. Meeting at 2 PM to finalize next week’s schedule.",
  "anonymous_tip": "Council, please guarantee a steady supply of safe flour for the co‑op next week and consider a temporary subsidy so villagers can afford bread while we recover.",
  "reason": "Day 5 is the final recall day; we must ensure refunds, verify safe flour supply, and prompt council support."
}

{
  "public_post": "Good news, villagers! Safe flour has been verified and we are back baking fresh, safe bread today. Come by the bakery for fresh loaves. If you feel any illness from earlier this week, please visit the clinic immediately. Thank you for your patience.",
  "coop_message": "Refund desk closed; all refunds processed. Inventory shows 120 fresh loaves ready. Bakers start at 8 AM. Keep an eye on any new illness reports and report to the clinic; update the council on sales and health monitoring.",
  "anonymous_tip": "Council, please ensure ongoing health monitoring for any post‑contamination symptoms and consider a temporary subsidy to keep affordable bread available while we recover.",
  "reason": "To inform villagers that safe bread is available, coordinate sales and health monitoring, and seek council support."
}

{
  "public_post": "Dear villagers, the recall and refunds for this week's bread are now complete, all contaminated loaves have been safely disposed, and we have secured a fresh safe‑flour shipment for next week; the Millbrook bakery will reopen on Monday with affordable bread. Thank you for your patience and please contact the clinic if you feel any symptoms.",
  "coop_message": "Team, all refunds processed and refund desk closed; inventory shows 0 contaminated loaves left. Safe flour shipment confirmed for next week, pricing will remain at 1 coin per loaf. Please prepare a communication plan to inform villagers on Monday and coordinate with council for a possible temporary subsidy.",
  "anonymous_tip": "Council, please consider a short‑term subsidy for the bakery next week to help villagers afford bread while we recover from the contamination incident.",
  "reason": "To finalize the recall, restore trust, and secure future sales."
}

{
  "public_post": "Good news, villagers! The bakery is fully back in operation with safe flour—fresh, healthy loaves are ready for purchase today. Refunds are complete, and we’re monitoring health; please let us know if you feel any lingering symptoms.",
  "coop_message": "All refunds processed and contaminated loaves disposed; confirm next week's safe flour shipment is secured and discuss a temporary price subsidy to help villagers recover financially.",
  "anonymous_tip": "Council, please consider a short‑term subsidy for bakery bread to offset the recent health incident and ensure all villagers can afford safe daily meals.",
  "reason": "To reassure villagers, restart sales, and secure ongoing safe flour and financial support."
}
